function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('.menu').each((_, menuEl) => {
    const $menu = $(menuEl);
    $menu.find('.menu-section').each((_, secEl) => {
      const $sec = $(secEl);
      // Section title (strip any price that might be embedded)
      let section = $sec
        .find('.menu-section-header .menu-section-title')
        .first()
        .text();
      section = cleanText(section);
      // Remove a trailing price like " 189,-" if present
      section = section.replace(/\s*\d+[.,]?\d*\s*[-,]?\s*$/, '').trim();
      if (section === '') section = null;

      $sec.find('.menu-item').each((_, itemEl) => {
        const $it = $(itemEl);
        // Dish name
        let name = $it.find('.menu-item-title').first().text();
        name = cleanText(name);
        if (!name) return; // skip empty names

        // Description (optional)
        let desc = $it.find('.menu-item-description').first().text();
        desc = desc ? cleanText(desc) : null;

        // Price – take the first non‑empty price element
        let priceText = $it
          .find('.menu-item-price-top, .menu-item-price-bottom')
          .first()
          .text();
        priceText = cleanText(priceText);
        const price = priceText ? parsePrice(priceText) : null;

        // Dedup across possible duplicated menus/tabs
        const key = (section || '') + '|' + name;
        if (!seen.has(key)) {
          seen.add(key);
          items.push({ section, name, description: desc, price });
        }
      });
    });
  });

  return items;
}
